      var veil=new GlassBackdrop(dashboard){Dock=DockStyle.Fill,Size=root.ClientSize};var popup=new GlassPopupPanel{Size=new Size(Math.Min(680,root.Width-80),scroll?Math.Min(460,root.ClientSize.Height-40):310)};veil.Controls.Add(popup);
