      Action close=()=>GlassTransition.Play(popup,true,()=>{root.Controls.Remove(veil);veil.Dispose();});veil.Click+=(s,e)=>close();
      var heading=new GlassLabel{Text=title,Font=new Font("Segoe UI Semibold",18,FontStyle.Bold),ForeColor=GlassInk.White,AutoSize=false,Location=new Point(26,25),Size=new Size(popup.Width-96,52)};popup.Controls.Add(heading);
