      var x=new GlassClose{Location=new Point(popup.Width-65,21)};x.Click+=(s,e)=>close();popup.Controls.Add(x);
      var ok=new ModernButton{Text="Понятно",BackColor=Color.Transparent,Font=new Font("Segoe UI Semibold",16,FontStyle.Regular,GraphicsUnit.Pixel),Primary=true,ForeColor=GlassInk.White,Location=new Point(popup.Width-155,popup.Height-65),Size=new Size(128,40)};ok.Click+=(s,e)=>close();popup.Controls.Add(ok);
      root.Controls.Add(veil);veil.BringToFront();GlassTransition.Play(popup,false,()=>ok.Focus());
    }
