    string VerifyRunningExit(){return ExitVerification.FirstSuccess(new[]{"https://www.gstatic.com/generate_204","https://www.cloudflare.com/cdn-cgi/trace"},VerifyExitTarget).GetAwaiter().GetResult();}
    void VerifyRunningTun(string target="https://www.gstatic.com/generate_204"){
      long offset=new FileInfo(core.LogPath).Length;
      var cert=Path.Combine(store.Root,"core","curl-ca-bundle.crt");
      var args="--silent --show-error --ipv4 --connect-timeout 3 --max-time 6 --noproxy \"*\" --cacert \""+cert+"\" --output NUL --write-out \"%{http_code}|%{local_ip}|%{local_port}\" "+target;
      string identity="";
      var start=new ProcessStartInfo(core.CurlExecutable,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
      using(var probe=Process.Start(start)){if(probe==null)throw new InvalidOperationException("Не удалось проверить TUN.");string code=probe.StandardOutput.ReadToEnd().Trim(),error=probe.StandardError.ReadToEnd().Trim();probe.WaitForExit();var fields=code.Split('|');if(probe.ExitCode!=0||fields.Length!=3||(fields[0]!="204"&&fields[0]!="200"))throw new InvalidOperationException("Сервер передаёт данные, но проверка TUN не прошла. "+error);identity="inbound connection from "+fields[1]+":"+fields[2];}
      System.Threading.Thread.Sleep(150);
      string captured;using(var stream=new FileStream(core.LogPath,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){stream.Seek(offset,SeekOrigin.Begin);using(var reader=new StreamReader(stream))captured=reader.ReadToEnd();}
      if(!captured.Contains("inbound/tun[tun-in]")||!captured.Contains(identity))throw new InvalidOperationException("Не подтверждён захват проверочного запроса интерфейсом TUN.");
    }
    void ProbeHttp(bool proxy){var cert=System.IO.Path.Combine(store.Root,"core","curl-ca-bundle.crt");var args="--silent --show-error --max-time 18 "+(proxy?"--noproxy \"\" --proxy http://127.0.0.1:10809 ":"--noproxy \"*\" ")+"--cacert \""+cert+"\" --output NUL --write-out \"%{http_code}\" https://www.gstatic.com/generate_204";var psi=new ProcessStartInfo(core.CurlExecutable,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var probe=Process.Start(psi)){if(probe==null)throw new InvalidOperationException("Не удалось запустить сетевую проверку.");var code=probe.StandardOutput.ReadToEnd().Trim();var error=probe.StandardError.ReadToEnd().Trim();if(!probe.WaitForExit(22000)){probe.Kill();throw new TimeoutException("Проверка превысила 22 секунды.");}if(probe.ExitCode!=0||code!="204")throw new InvalidOperationException((error.Length>0?error:"HTTP "+code));}}
    async void RunTunTest(){
      if(state.Mode!="tun"){GlassNotice.Show(this,"Выберите режим TUN в настройках.","Проверка TUN");return;}
      if(!IsAdministrator()){RequestElevation("--tun-test");return;}
      try{
        var report=await Task.Run(()=>{
          var wasRunning=core.Running;
          var selected=Selected();
          if(selected==null)throw new InvalidOperationException("Сначала выберите сервер. Проверка TUN должна проверить и удалённый выход.");
          var test=new ClientState{Mode="tun",SelectedServerId=selected.Id,AutoSelect=state.AutoSelect,Servers=state.AutoSelect?state.Servers.ToList():new List<ServerNode>{selected},DnsProvider=state.DnsProvider,DnsProtocol=state.DnsProtocol,DnsCustom=state.DnsCustom,Lists=new List<RouteList>{new RouteList{Name="Проверка TUN",Text="www.gstatic.com",Target="proxy"}}};
          try{
            if(!wasRunning)core.Start(test);
            long offset=new FileInfo(core.LogPath).Length;
            try{ProbeHttp(true);}catch(Exception ex){throw new InvalidOperationException("Удалённый VPN-выход не отвечает даже без TUN: "+ex.Message+". Проверьте другой узел или настройки сервера.");}
            if(!wasRunning){try{ProbeHttp(false);}catch(Exception ex){throw new InvalidOperationException("Удалённый выход работает, но запрос через TUN не прошёл: "+ex.Message+". Проверьте DNS и маршруты.");}}
            System.Threading.Thread.Sleep(400);
            string fresh;
            using(var stream=new FileStream(core.LogPath,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){stream.Seek(offset,SeekOrigin.Begin);using(var reader=new StreamReader(stream))fresh=reader.ReadToEnd();}
            bool captured=fresh.Contains(wasRunning?"inbound/mixed[diagnostic]":"inbound/tun[tun-in]: inbound connection");
            if(!captured)throw new InvalidOperationException("HTTP 204 получен, но в журнале нет подтверждения захвата проверочного запроса.");
            return wasRunning?"Запрос HTTP 204 прошёл через выбранный сервер. Сетевой выход работает.":"TUN захватил запрос; выбранный сервер передал его; получен HTTP 204.";
          }finally{if(!wasRunning)core.Stop();}
        });
        verifiedThisSession=core.Running;WriteLog("Проверка соединения: TUN и удалённый выход подтвердили HTTP 204");if(page=="home")ShowPage("home");
        GlassNotice.Show(this,report,"Проверка TUN пройдена",MessageBoxButtons.OK,MessageBoxIcon.Information);
      }catch(Exception ex){WriteLog("Ошибка проверки TUN: "+ex.Message);GlassNotice.Show(this,ex.Message,"Проверка TUN не пройдена",MessageBoxButtons.OK,MessageBoxIcon.Error);}
    }
