    async void ToggleConnection(object sender,EventArgs e){
      if(state.IndependentWarpOutputs){ToggleRoutedOutput(false);return;}
      if(discordVoiceChecking){Toast("Сначала закройте проверку голоса Discord");return;}
      if(setupCancellation!=null){Toast("Дождитесь завершения мастера или отмените проверку");return;}
      if(InvokeRequired){BeginInvoke(new Action(()=>ToggleConnection(sender,e)));return;}
      if(connecting)return;
      if(!core.Running&&!state.AutoSelect&&Selected()!=null&&!core.HasEngine(Selected())){await OfferEngineDownload(new[]{Selected()});return;}
      if(zapretCancellation!=null&&state.Mode=="tun"&&!core.Running){Toast("Дождитесь завершения подбора Zapret, прежде чем включать TUN");return;}
      bool keepSettings=(page=="settings"||page=="warp"||page=="modules")&&popupOverlay!=null;
      System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());
      if(core.Running){++connectionGeneration;expectedRunning=false;verifiedThisSession=false;connectedAtUtc=DateTime.MinValue;connecting=true;blueDashboard.Invalidate();RefreshSettingsConnection();try{await Task.Run(()=>{systemProxy.Restore();core.Stop();});WriteLog("Подключение остановлено");}finally{connecting=false;switching=false;FinishConnectionPage(keepSettings);}return;}
      if(state.Mode=="tun"&&!IsAdministrator()){RequestElevation("--connect");return;}
      int token=++connectionGeneration;connecting=true;verifiedThisSession=false;blueTraffic.Reset();blueDashboard.Invalidate();RefreshSettingsConnection();
      try{await Task.Run(()=>{systemProxy.Restore();core.Start(state);});if(IsDisposed){core.Stop();return;}expectedRunning=true;connectedAtUtc=DateTime.UtcNow;RememberServer(Selected());store.Save(state);WriteLog(state.Mode=="proxy"?"Локальный HTTP / SOCKS5: 127.0.0.1:10808. Windows не изменён":"TUN запущен; проверяем передачу данных");FinishConnectionPage(keepSettings);CheckSession(token);}
      catch(Exception ex){expectedRunning=false;verifiedThisSession=false;core.Stop();WriteLog("Ошибка запуска: "+ex.Message);FinishConnectionPage(keepSettings);GlassNotice.Show(this,ex.Message,"Не удалось запустить подключение",MessageBoxButtons.OK,MessageBoxIcon.Error);}
      finally{connecting=false;switching=false;if(!IsDisposed){blueDashboard.Invalidate();RefreshSettingsConnection();}}
    }
    void FinishConnectionPage(bool keepSettings){if(keepSettings&&popupOverlay!=null)RefreshSettingsConnection();else ShowPage("");}
    void RefreshSettingsConnection(){
      if(content==null||content.IsDisposed)return;
      if(page=="warp"||page=="modules"){
        var toggle=content.Controls.Find("warpConnectionToggle",true).FirstOrDefault();if(toggle!=null){bool active=core.Running&&state.WarpEnabled;toggle.Text=connecting?"Подождите…":active?"Отключить WARP":"Подключить сохранённый";toggle.Enabled=!connecting&&warpCancellation==null&&toggle.Tag!=null;toggle.Visible=false;}
        return;
      }
      if(page!="settings")return;
      foreach(string key in new[]{"settingsConnectionToggle","modePicker","dnsType","dnsProvider","dnsCustom","settingsRights","settingsVerify"}){
        var control=content.Controls.Find(key,true).FirstOrDefault();if(control==null)continue;
        if(key=="settingsConnectionToggle"){control.Text=connecting?"Подождите…":core.Running?"Выключить":"Включить";control.Enabled=!connecting;}
        else if(key=="settingsRights")control.Enabled=!connecting&&!core.Running&&!IsAdministrator();
        else if(key=="settingsVerify")control.Enabled=!connecting&&state.Mode=="tun";
        else if(key=="dnsCustom")control.Enabled=!connecting&&!core.Running&&state.DnsProvider=="Свой";
        else control.Enabled=!connecting&&!core.Running;
      }
    }
    async void CheckSession(int token){
      string error=null;
      long exitTime=0,tunTime=0;await Task.Run(()=>{var watch=Stopwatch.StartNew();try{string target=VerifyRunningExit();exitTime=watch.ElapsedMilliseconds;watch.Restart();if(state.Mode=="tun")VerifyRunningTun(target);tunTime=watch.ElapsedMilliseconds;}catch(Exception ex){if(exitTime==0)exitTime=watch.ElapsedMilliseconds;else tunTime=watch.ElapsedMilliseconds;error=ex.Message;}});
      if(IsDisposed||token!=connectionGeneration||!core.Running)return;
      WriteLog("VPN · Проверка удалённого выхода: "+exitTime+" мс; проверка захвата TUN: "+tunTime+" мс");
      verifiedThisSession=error==null;
      WriteLog(error==null?"Передача данных через VPN подтверждена":"Подключение оставлено включённым; проверка не прошла: "+error);
      blueDashboard.Invalidate();if(error!=null)Toast("Подключение включено. Проверка не прошла — откройте журнал.");
    }
