      catch(Exception ex){core.Stop();connectedAtUtc=DateTime.MinValue;WriteLog("Перезапуск выходов не удался: "+ex.Message);if(!IsDisposed)GlassNotice.Show(this,ex.Message,"Не удалось перезапустить выходы");}
