    IEnumerable<string> SubscriptionSources(){return state.Servers.Select(n=>n.Source).Concat(state.SubscriptionUrls??new List<string>()).Concat(new[]{state.SubscriptionUrl}).Where(x=>!String.IsNullOrWhiteSpace(x)).Distinct();}
    async Task<bool> ImportBatch(string value,bool navigate=true){
      if(String.IsNullOrWhiteSpace(value))return false;
      if(value.TrimStart().StartsWith("[Interface]",StringComparison.OrdinalIgnoreCase))return await ImportText(value,navigate);
      var lines=value.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToArray();
      var subscriptions=lines.Where(x=>{Uri uri;return Uri.TryCreate(x,UriKind.Absolute,out uri)&&uri.Scheme=="https"&&uri.UserInfo.Length==0;}).Distinct().ToArray();
      bool ok=true;var keys=String.Join(Environment.NewLine,lines.Except(subscriptions));
      if(!String.IsNullOrWhiteSpace(keys))ok=await ImportText(keys,navigate)&&ok;
      foreach(var url in subscriptions)ok=await ImportText(url,navigate)&&ok;
      if(lines.Length==1&&subscriptions.Length==0&&String.IsNullOrWhiteSpace(keys))return false;
      return ok;
    }
    async Task<bool> ImportText(string value,bool navigate=true){if(InvokeRequired){var result=new TaskCompletionSource<bool>();BeginInvoke(new Action(async()=>{try{result.SetResult(await ImportText(value,navigate));}catch(Exception ex){result.SetException(ex);}}));return await result.Task;}if(!(System.Threading.SynchronizationContext.Current is WindowsFormsSynchronizationContext))System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());if(value.Length==0)return false;try{string source=null;if(value.StartsWith("https://",StringComparison.OrdinalIgnoreCase)){source=value;value=await core.DownloadTextAsync(value);}var imported=Links.Read(value);if(imported.Count==0)throw new FormatException("Не найдены поддерживаемые ссылки или конфигурация.");if(await OfferEngineDownload(imported.ToArray()))return false;foreach(var n in imported)core.ValidateImport(n);SubscriptionMerge.Apply(state,imported,source);if(source!=null&&core.Running)RestartConnection();store.Save(state);WriteLog("Импортировано серверов: "+imported.Count);if(navigate){await ProbeAllAsync();ShowPage("servers");}return true;}catch(Exception ex){WriteLog("Ошибка импорта: "+ex.Message);GlassNotice.Show(this,ex.Message,"Ошибка импорта",MessageBoxButtons.OK,MessageBoxIcon.Error);return false;}}
