    async void RestoreSettings(){
      if(connecting||warpCancellation!=null||zapretCancellation!=null||byetubeCancellation!=null||setupCancellation!=null||discordVoiceChecking||gameRecording.Running){Toast("Сначала завершите текущую операцию");return;}
      using(var picker=new OpenFileDialog{Title="Выберите client.json из бэкапа MCRF",Filter="Бэкап MCRF (client.json)|client.json",InitialDirectory=Path.Combine(store.Root,"reset-backups")}){
        if(picker.ShowDialog(this)!=DialogResult.OK)return;
        try{string folder=Path.GetDirectoryName(picker.FileName);if(String.Equals(Path.GetFullPath(folder),store.Root,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Выберите файл из папки бэкапа, а не текущий профиль.");var restored=new StateStore(folder).Load();
          if(!await ConfirmChange("Заменить текущие настройки выбранным бэкапом? Текущие настройки сохраним отдельно. Если бэкап содержит hosts, восстановим только блок MCRF; посторонние записи сохранятся. После восстановления откройте программу снова.","Восстановить бэкап","Восстановление"))return;
          if(connecting||warpCancellation!=null||zapretCancellation!=null||byetubeCancellation!=null||setupCancellation!=null||discordVoiceChecking||gameRecording.Running){Toast("Дождитесь окончания текущей операции");return;}

          zapret.Stop();telegramBridge.Stop();core.Stop();systemProxy.Restore();expectedRunning=false;
          ProfileReset.Restore(store,folder,true);
          state=restored;GlassNotice.Show(this,"Бэкап восстановлен. Откройте программу снова.","Готово");Close();
        }catch(Exception ex){GlassNotice.Show(this,"Не удалось восстановить бэкап: "+ex.Message,"Восстановление");}
      }
    }
    async void ResetSettings(){
      if(connecting||warpCancellation!=null||zapretCancellation!=null||byetubeCancellation!=null||setupCancellation!=null||discordVoiceChecking||gameRecording.Running){Toast("Сначала завершите текущую проверку или запись");return;}
